output.text:
    // thread — group thread reply OR DM thread reply alike. Slack encodes
    // `slack:{channel}:{thread_ts}` (top-level DM has empty thread_ts so the id
    // ends with a trailing `:`); Telegram encodes `telegram:{chatId}` for
    // top-level and `telegram:{chatId}:{topicId}` inside a forum topic. Without
    // this, a `onDirectMessage` event for a reply in a DM thread (e.g. the
    // worker posted a scheduled-fire follow-up message and the user
    // clicked Reply on it) would fall back to the channel id and the bot's
    // response would land in the main DM pane instead of the thread.
    const isThreadReply =
      typeof thread.id === "string" &&
      thread.id !== channelId &&
      thread.id !== `${channelId}:`;
    const conversationId =
      isGroup || isThreadReply ? (thread.id as string) : channelId;

    logger.info(
      {
        connectionId: connection.id,
        platform,
        userId,
        channelId,
        messageId,
        source,
      },
      "Processing inbound message"
    );

    // Gap 6: Allowlist check
    if (!isSenderAllowed(connection.settings?.allowFrom, userId)) {
      logger.info({ userId }, "Blocked by allowlist");
      return;
    }

    // Gap 6: Group check
    if (isGroup && connection.settings?.allowGroups === false) {
      logger.info({ channelId }, "Groups not allowed");
      return;
    }

    // Subscribe to thread for follow-up messages
    if (source === "mention" || source === "dm") {
      try {
        await thread.subscribe();
      } catch {
        // some platforms may not support subscribe
      }
    }

    // Resolve agent ID: a channel Event Behavior wins, otherwise the connection's
    // owning agent. No more shadow agent creation — if neither matches we
    // drop the message.
    const behaviorSubscriptionService =
      this.services.getBehaviorSubscriptionService();
    const rawTeamId =
      (message.raw as Record<string, unknown> | undefined)?.team_id ??
      (message.raw as Record<string, unknown> | undefined)?.team;
    const teamId = typeof rawTeamId === "string" ? rawTeamId : undefined;

    // Preview connections fan out to Behaviors in OTHER orgs (a
    // `/lobu link <code>` creates one under the claim's org, not this
    // connection's), so plan org-agnostically and route by the Behavior's org.
    const isPreview = this.connection.settings?.previewMode === true;
    const normalizedChannelId = stripPlatformPrefix(platform, channelId);
    const behaviorSignal = {
      connector_key: platform,
      resource_type: "channel",
      resource_ref: teamId
        ? `${platform}:channel:${teamId}:${normalizedChannelId}`
        : `${platform}:channel:${normalizedChannelId}`,
      event_type: "message.created",
      delivery_id: `chat:${this.connection.id}:${messageId}`,
      label: `${platform} message in ${normalizedChannelId}`,
      input_text: typeof message.text === "string" ? message.text : "",
      occurred_at:
        message.metadata?.dateSent instanceof Date
          ? message.metadata.dateSent.toISOString()
          : new Date().toISOString(),
      attributes: {
        channel_id: normalizedChannelId,
        channel_key: channelId,
        user_id: userId,
        is_mention: source === "mention" || message.isMention === true,
        mention_only: source === "mention" || message.isMention === true,
        ...(teamId ? { team_id: teamId } : {}),
        ...(conversationId !== channelId ? { thread_id: conversationId } : {}),
      },
    };
    const behaviorPlan = this.connection.organizationId
      ? await this.behaviorPlanner({
          connectionOrganizationId: this.connection.organizationId,
          runtimeConnectionId: this.connection.id,
          signal: behaviorSignal,
          crossOrganization: isPreview,
        })
      : {
          signal: behaviorSignal,
          replyTargets: [],
          backgroundTargets: [],
        };
    const replyBehaviors = behaviorPlan.replyTargets;
    const backgroundBehaviors = behaviorPlan.backgroundTargets;
    const behavior = replyBehaviors[0] ?? backgroundBehaviors[0];
    // The planner above is the only Behavior routing decision because it
    // evaluates the complete trigger predicate. A channel-only subscription
    // lookup here would re-select Behaviors rejected by mention/team filters.
    const fallbackResolved = behavior
      ? null
      : await resolveAgentId({
          platform,
          channelId,
          agentId: this.connection.agentId,
          organizationId: this.connection.organizationId,
        });
    const resolved = behavior
      ? {
          agentId: behavior.agentId,
          source: "behavior" as const,
          organizationId: behavior.organizationId,
          model: behavior.model ?? undefined,
          instructions: behavior.instructions,
          behaviorId: behavior.behaviorId,
        }
      : fallbackResolved;
    if (!resolved) {
      // Linked channel but trigger filters rejected this message (e.g.
      // mention_only on a non-mention). The planner is the authority for
      // activation; do not fall through to the "unlinked" notice or the notice
      // would spam every ordinary message in a mention-only linked channel.
      if (
        behaviorSubscriptionService &&
        this.connection.organizationId &&
        (await behaviorSubscriptionService.channelHasMessageSubscription(
          this.connection.id,
          channelId,
          this.connection.organizationId,
          isPreview
        ))
      ) {
        logger.info(
          { platform, channelId, teamId, connectionId: this.connection.id },
          "Channel has Behavior subscription(s) but none matched this message — dropping"
        );
        return;
      }

      // An unrouted chat still has to honor commands: the unlinked notice
      // below tells the user to paste `/link <code>` (or `/lobu link <code>`)
      // into this same chat. Slack delivers those natively via the
      // `onSlashCommand` ingress, but every other platform delivers them as
      // plain message text — which used to die in this dead end before the
      // dispatcher ever saw it (#2230).
      if (this.commandDispatcher) {
        const handled = await this.commandDispatcher.tryHandleSlashText(
          this.stripBotMention(
            typeof message.text === "string" ? message.text : ""
          ),
          {
            platform,
            userId,
            channelId,
            teamId,
    // Preview-link redemption as plain message text — preview connections only.
    // In an AI-app DM Slack won't deliver `/lobu link <code>` as a slash command,
    // so a hosted preview bot accepts the code as a message — `link <code>` or a
    // bare `<slug>-<CODE>` paste — and redeems via the same `link` command. Gated
    // to previewMode so a normal agent bot's DMs (where a code-looking message is
    // just chat for the agent) are never swallowed. Runs before the worker
    // enqueue and the previewMode menu so a pasted code binds.
    if (
      !sessionReset &&
      !bangBash &&
      this.commandDispatcher &&
      this.connection.settings?.previewMode === true
    ) {
      const linkCode = parsePreviewLinkCode(messageText, isGroup);
      if (linkCode) {
        const handled = await this.commandDispatcher.tryHandle(
          "link",
          linkCode,
          {
            platform,
            userId,
            channelId,
            teamId,
            isGroup,
            conversationId,
            connectionId: this.connection.id,
            organizationId: this.connection.organizationId,
            reply: createChatReply((content) => thread.post(content)),
          }
        );
        if (handled) return;
      }
    }

    // Slash command dispatch — intercept before queueing to worker
    if (!sessionReset && !bangBash && this.commandDispatcher) {
      const handled = await this.commandDispatcher.tryHandleSlashText(
        messageText,
        {
          platform,
          userId,
          channelId,
          teamId,
          isGroup,
          conversationId,
          connectionId: this.connection.id,
          organizationId: this.connection.organizationId,
          reply: createChatReply((content) => thread.post(content)),
        }
      );
      if (handled) return;
    }

    // Preview connection (a hosted Lobu workspace bot — Slack, Telegram, …):
    // an unlinked DM/@-mention that ISN'T a command. Don't run the connection's
    // placeholder owning agent — reply with the "pick a demo agent" menu (or the
    // "wire your own agent" instructions) and stop. This MUST come after the
    // slash dispatch above: `/lobu link <code>` / `/lobu try <id>` arrive as
    // slash commands in channels, but as plain message text in an "Agents & AI
    // Apps" DM — they have to bind/pick via the dispatcher before we'd otherwise
    // preempt them with this menu.
    if (
      resolved.source === "connection" &&
      this.connection.settings?.previewMode === true
    ) {
      const notice = await previewUnlinkedNotice(platform, this.connection.id);
      if (notice) {
        logger.info(
          { platform, channelId, teamId, connectionId: this.connection.id },
          "Preview connection: unlinked chat — replying with demo-agent menu"
        );
        await thread.post(notice);
        return;
      }
    }

    // Gap 1: Retrieve + append conversation history via the SDK state adapter.
    const conversationState = this.conversationState();

    // Backfill: when the bot is first activated in a thread (mention or
    // first subscribed event), ask the Chat SDK adapter for the thread's
    // prior messages. Slack maps this to `conversations.replies` (Tier 3,
    // generous limit). Without this, a mid-thread mention has no context
    // for the messages that preceded it. `claimThreadBackfill` is an
    // atomic per-thread one-shot guard — runs at most once per thread per
    // HISTORY_TTL_MS window, regardless of how many events race in.
    if (
      conversationState &&
      isGroup &&
      (await conversationState.claimThreadBackfill(
        this.connection.id,
        case "no_connection":
          await ctx.reply(
						"This chat isn't connected to a Lobu preview workspace.",
          );
          return;
      }
    },
  });

  registry.register({
    name: "agents",
    description: "List the demo agents you can try here",
    handler: async (ctx: CommandContext) => {
      await replyDemoMenu(ctx);
    },
  });

  // Slack Preview: redeem a `/lobu link <code>` minted by `lobu run` and bind
  // this channel/DM to that agent. Re-running it with a different code rebinds.
  // (Slack only delivers the natively-registered `/lobu` slash command, so this
  // is reached as the `link` subcommand — not a bare `/link`.)
  registry.register({
    name: "link",
    // `/help` renders this on every platform, so it stays code-only; the
    // Slack-only `<agentId>` shortcut is surfaced by `agentIdHint` below.
    description: "Link this chat to a Lobu agent with a `<code>` from `lobu run`",
    handler: async (ctx: CommandContext) => {
      const arg = ctx.args.trim();
      const cmd = ctx.platform === "slack" ? "/lobu link" : "/link";
      // The codeless `<agentId>` shortcut needs a workspace-scoped Slack
      // identity, which only Slack sign-in and the install claim write — so it
      // never applies on other platforms. Don't promise it there.
      const agentIdHint =
        ctx.platform === "slack"
          ? " (If you connected this workspace to Lobu, `/lobu link <agentId>` works too.)"
          : "";
      if (!arg) {
        await ctx.reply(
					`Usage: \`${cmd} <code>\` — get a code by running \`lobu run\` on a Preview-enabled agent.${agentIdHint}`,
        );
        return;
      }
      const surfaceType: "dm" | "channel" = ctx.isGroup ? "channel" : "dm";
      // The message handler looks bindings up by the platform's canonical
      // channel-id form; Slack slash commands hand us the bare id.
      const channelId =
        ctx.platform === "slack"
          ? canonicalSlackChannelId(ctx.channelId)
          : ctx.channelId;
      const result = await consumePreviewClaim({
        code: arg,
        platform: ctx.platform,
        teamId: ctx.teamId,
        channelId,
        surfaceType,
				connectionId: ctx.connectionId,
				connectionOrganizationId: ctx.organizationId,
      });
      switch (result.status) {
        case "bound":
          await ctx.reply(
						`Linked this chat to agent \`${result.agentId}\`. Say hi — I'll reply here from now on.`,
          );
          return;
        case "surface_not_allowed":
          await ctx.reply(
						`This code can't be used in a ${result.surfaceType === "dm" ? "DM" : "channel"}. Check the agent's \`preview.${ctx.platform}.surfaces\` setting.`,
					);
					return;
				case "connection_mismatch": {
					const allowedLocation =
						ctx.platform === "slack"
							? "Lobu's hosted Slack workspace or a Slack workspace"
							: "Lobu's hosted preview bot or a chat connection";
					const currentLocation =
						ctx.platform === "slack"
							? "this Slack workspace"
							: "this chat connection";
					await ctx.reply(
						`That code can only be used with ${allowedLocation} connected to the same Lobu organization as the agent. Open the preview link from \`lobu run\`, or connect ${currentLocation} to the agent's organization.`,
					);
					return;
				}
        case "not_found": {
          // Not a valid code — but if we already know who this chat user is,
          // treat the arg as an agent id and re-bind directly (no fresh code
          // needed). Identity comes only from Slack sign-in / the install claim
          // (slack-claim.ts), never from redeeming a code: the same mapping
          // authorizes Slack approvals, so a pasted code must not mint it.
          const lobuUserId = await resolveChatUserIdentity(
            ctx.platform,
            ctx.teamId,
						ctx.userId,
          );
          if (lobuUserId) {
            const bound = await bindChatToAgentForOwner({
              platform: ctx.platform,
              teamId: ctx.teamId,
              channelId,
              agentId: arg,
              lobuUserId,
							connectionId: ctx.connectionId ?? "",
							connectionOrganizationId: ctx.organizationId,
            });
            if (bound.status === "bound") {
              await ctx.reply(
								`Linked this chat to agent \`${arg}\`. Say hi — I'll reply here from now on.`,
              );
              return;
            }
            await ctx.reply(
							`No agent \`${arg}\` you can manage in your orgs. Either run \`lobu apply\` to register it, or paste a fresh \`/lobu link <code>\` from \`lobu run\`.`,
            );
            return;
          }
          await ctx.reply(
						`That link code is invalid or expired. Run \`lobu run\` again to get a fresh one.${agentIdHint}`,
          );
          return;
        }
      }
    },
  });
}
	 * Materialize the chat-link Behavior after a group message routes through the
	 * connection-owner fallback. Returns false when the active, org-scoped chat
	 * connection cannot be resolved. createChatBehavior serializes concurrent
	 * attempts for the same connection and channel.
	 */
	async materializeConnectionFallbackLink(
		connectionId: string,
		organizationId: string,
		agentId: string,
		platform: string,
		channelId: string,
		teamId: string | undefined,
	): Promise<boolean> {
		const sql = getDb();
		const slug = runtimeConnectionIdToSlug(connectionId);
		const rows = (await sql`
			SELECT id
			FROM connections
			WHERE slug = ${slug}
			  AND organization_id = ${organizationId}
			  AND connector_key = ${platform}
			  AND credential_mode IS NOT NULL
			  AND status = 'active'
			  AND deleted_at IS NULL
			LIMIT 1
		`) as Array<{ id: number | string }>;
		const numericId = rows[0] ? Number(rows[0].id) : NaN;
		if (!Number.isInteger(numericId) || numericId < 1) return false;
		// create-only: never overwrite an explicit link that a concurrent
		// `/lobu link` may have committed — the check happens under the advisory
		// lock inside createChatBehavior, so it is race-safe across replicas.
		await this.createChatBehavior(agentId, platform, channelId, teamId, {
			organizationId,
			connectionId: numericId,
			createOnly: true,
		});
		return true;
	}

	async createChatBehavior(
		agentId: string,
		platform: string,
		channelId: string,
		teamId: string | undefined,
		options: {
			configuredBy?: string;
			organizationId?: string;
			sql?: DbClient;
			connectionId: number;
			model?: string;
			/**
			 * Create-only: when a chat-link already covers this connection+channel,
			 * preserve it and return instead of relinking it to `agentId`. Used by
			 * the connection-owner fallback so it can never overwrite an explicit
			 * `/lobu link` that committed between the caller's check and this write
			 * — the decision is made under the advisory lock, so it holds across
			 * replicas. Explicit link/relink flows omit it and keep relinking.
			 */
			createOnly?: boolean;
		},
	): Promise<void> {
		if (!Number.isInteger(options.connectionId) || options.connectionId < 1) {
			throw new Error("connectionId must be a positive integer");
		}
		const sql = options.sql ?? getDb();
		const organizationId = requireOrgId(
			options.organizationId,
			"BehaviorSubscriptionService.createChatBehavior",
		);
		const model = options.model?.trim() || null;
		const trigger = eventTrigger({
			platform,
			connectionId: options.connectionId,
			channelId,
			teamId,
		});

		const write = async (tx: DbClient): Promise<void> => {
			// Serialize concurrent create/relink for the same org+connection+channel.
			await tx`
				SELECT pg_advisory_xact_lock(
					hashtext('behavior_chat_link'),
					hashtext(${`${organizationId}:${options.connectionId}:${channelId}`})
				)
			`;
			const connectionRows = await tx`
				SELECT 1
				FROM connections
				WHERE id = ${options.connectionId}
				  AND connector_key = ${platform}
				  AND deleted_at IS NULL
				LIMIT 1
			`;
			if (connectionRows.length === 0) {
				throw new Error(
					`Connection ${options.connectionId} is not an active ${platform} connection.`,
				);
			}

			const existing = await tx<{ behavior_id: number }>`
				SELECT w.id AS behavior_id
				FROM watchers w
				CROSS JOIN LATERAL jsonb_array_elements(COALESCE(w.triggers, '[]'::jsonb)) trigger
				WHERE w.status = 'active'
				  AND w.organization_id = ${organizationId}
				  AND trigger->>'kind' = 'event'
				  AND trigger->>'connector_key' = ${platform}
				  AND jsonb_typeof(trigger->'connection_id') = 'number'
				  AND (trigger->>'connection_id')::bigint = ${options.connectionId}
				  AND trigger->'event_types' ? 'message.created'
				  AND trigger->'match'->>'channel_id' = ${nativeChannelId(platform, channelId)}
				  AND w.tags @> ARRAY[${CHAT_LINK_TAG}]::text[]
				ORDER BY w.updated_at DESC, w.id DESC
				LIMIT 1
				FOR UPDATE OF w
			`;
			if (existing[0]) {
				// A chat-link already covers this connection+channel. Under
				// create-only (the connection-owner fallback), leave it untouched —
				// this is where a racing explicit `/lobu link` is preserved.
				if (options.createOnly) return;
				// Relink must not wipe user-added triggers (schedule, extra events)
				// on the same Behavior — only replace the chat message.created
				// trigger for this connection+channel.
				const [row] = await tx<{ triggers: unknown }>`
					SELECT triggers FROM watchers WHERE id = ${existing[0].behavior_id}
				`;
				const prev = Array.isArray(row?.triggers) ? row.triggers : [];
				const native = nativeChannelId(platform, channelId);
				const kept = prev.filter((candidate) => {
					if (!candidate || typeof candidate !== "object") return true;
					const t = candidate as Record<string, unknown>;
					if (t.kind !== "event") return true;
					if (t.connector_key !== platform) return true;
					if (Number(t.connection_id) !== options.connectionId) return true;
					const eventTypes = t.event_types;
					if (
						!Array.isArray(eventTypes) ||
						!eventTypes.includes("message.created")
					) {
						return true;
					}
					const match =
						t.match && typeof t.match === "object"
							? (t.match as Record<string, unknown>)
							: null;
					if (match?.channel_id !== native) return true;
					return false;
				});
				await tx`
					UPDATE watchers
					SET agent_id = ${agentId},
						triggers = ${tx.json([...kept, trigger])},
						execution_config = CASE
							WHEN ${model}::text IS NULL
								THEN NULLIF(COALESCE(execution_config, '{}'::jsonb) - 'model', '{}'::jsonb)
							ELSE COALESCE(execution_config, '{}'::jsonb) || jsonb_build_object('model', ${model}::text)
						END,
						updated_at = current_timestamp
					WHERE id = ${existing[0].behavior_id}
				`;
				return;
			}

			const createdBy = await resolveCreatedBy(
				tx,
				organizationId,
				agentId,
				options.configuredBy,
			);
			const watcherId = await getNextNumericId(tx, "watchers");
			const versionId = await getNextNumericId(tx, "watcher_versions");
			await tx`
				INSERT INTO watchers (
					id, name, slug, description, organization_id, entity_ids,
					schedule, next_run_at, triggers, agent_id, model_config,
					execution_config, sources, version, current_version_id, tags,
					status, created_by, created_at, updated_at, watcher_group_id
				) VALUES (
					${watcherId}, ${`Messages in ${channelId}`}, ${`chat-${platform}-${watcherId}`},
					'Chat subscription', ${organizationId}, '{}'::bigint[],
					NULL, NULL, ${tx.json([trigger])}, ${agentId}, '{}'::jsonb,
					${model ? tx.json({ model }) : null}, '[]'::jsonb, 1, NULL,
					ARRAY[${CHAT_LINK_TAG}]::text[], 'active', ${createdBy},
					current_timestamp, current_timestamp, ${watcherId}
				)
			`;
			await tx`
				INSERT INTO watcher_versions (
					id, watcher_id, version, name, description, prompt,
					version_sources, change_notes, created_by, created_at
				) VALUES (
					${versionId}, ${watcherId}, 1, ${`Messages in ${channelId}`},
					'Chat subscription', ${CHAT_LINK_PROMPT}, '[]'::jsonb,
					'Created from chat link', ${createdBy}, current_timestamp
				)
			`;
			await tx`
				UPDATE watchers SET current_version_id = ${versionId}
				WHERE id = ${watcherId}
			`;
		};
		if (options.sql) await write(sql);
		else await sql.begin(write);

		await resolveStreamingChannelFeedId({
			connectionId: String(options.connectionId),
			organizationId,
			channelKey: `${platform}:${nativeChannelId(platform, channelId)}`,
			sql,
		});
		});
		logger.info(`Created chat Behavior: ${platform}/${channelId} → ${agentId}`);
	}

	async archiveChatBehavior(
		agentId: string,
		channelId: string,
		connectionId: number,
		organizationId: string,
		options?: { sql?: DbClient },
	): Promise<boolean> {
		const sql = options?.sql ?? getDb();
		const orgId = requireOrgId(
			organizationId,
			"BehaviorSubscriptionService.archiveChatBehavior",
		);
		const write = async (tx: DbClient): Promise<boolean> => {
			const rows = await tx<{ id: number; platform: string }>`
				SELECT w.id, trigger->>'connector_key' AS platform
				FROM watchers w
				CROSS JOIN LATERAL jsonb_array_elements(COALESCE(w.triggers, '[]'::jsonb)) trigger
				WHERE w.status = 'active'
				  AND w.organization_id = ${orgId}
				  AND w.agent_id = ${agentId}
				  AND trigger->>'kind' = 'event'
				  AND jsonb_typeof(trigger->'connection_id') = 'number'
				  AND (trigger->>'connection_id')::bigint = ${connectionId}
				  AND trigger->'event_types' ? 'message.created'
				  AND trigger->'match'->>'channel_id' = ${nativeChannelIdFromAny(channelId)}
				  AND w.tags @> ARRAY[${CHAT_LINK_TAG}]::text[]
				FOR UPDATE OF w
			`;
			const archived = rows[0];
			if (!archived) return false;
			await tx`
				UPDATE watchers
				SET status = 'archived', updated_at = current_timestamp
				WHERE id = ANY(${pgBigintArray(rows.map((row) => row.id))}::bigint[])
			`;
			const native = nativeChannelIdFromAny(channelId);
			const canonicalChannelId = `${archived.platform}:${native}`;
			if (
				!(await hasChannelSubscription(
					tx,
					String(connectionId),
					canonicalChannelId,
				))
			) {
				await softDeleteStreamingChannelFeed({
					connectionId: String(connectionId),
					channelKey: canonicalChannelId,
					sql: tx,
				});
			}
			return true;
		};
		return options?.sql ? write(sql) : sql.begin(write);
	}

	async listChatBehaviors(
		agentId: string,
		organizationId: string,
	): Promise<ChatBehaviorSubscription[]> {
		const sql = getDb();
		const orgId = requireOrgId(
			organizationId,
			"BehaviorSubscriptionService.listChatBehaviors",
		);
		return loadChatBehaviorSubscriptions(sql, {
			behaviorOrganizationId: orgId,
			agentId,
			oldestFirst: true,
		});
	}

	async archiveAllChatBehaviors(
		agentId: string,
		organizationId: string,
	): Promise<number> {
		const sql = getDb();
		const orgId = requireOrgId(
			organizationId,
			"BehaviorSubscriptionService.archiveAllChatBehaviors",
		);
		return sql.begin(async (tx) => {
			const rows = await tx<{
				behavior_id: number;
				connection_id: string;
				channel_id: string;
			}>`
				SELECT
					w.id AS behavior_id,
					(trigger->>'connection_id')::text AS connection_id,
					COALESCE(
						NULLIF(trigger->'match'->>'channel_key', ''),
						(trigger->>'connector_key') || ':' || (trigger->'match'->>'channel_id')
					) AS channel_id
				FROM watchers w
				CROSS JOIN LATERAL jsonb_array_elements(COALESCE(w.triggers, '[]'::jsonb)) trigger
				WHERE w.status = 'active'
				  AND w.organization_id = ${orgId}
				  AND w.agent_id = ${agentId}
				  AND trigger->>'kind' = 'event'
				  AND jsonb_typeof(trigger->'connection_id') = 'number'
				  AND trigger->'event_types' ? 'message.created'
				  AND trigger->'match'->>'channel_id' IS NOT NULL
				  AND w.tags @> ARRAY[${CHAT_LINK_TAG}]::text[]
				FOR UPDATE OF w
			`;
			if (rows.length > 0) {
				await tx`
					UPDATE watchers
					SET status = 'archived', updated_at = current_timestamp
					WHERE id = ANY(${pgBigintArray(rows.map((row) => row.behavior_id))}::bigint[])
				`;
			}
			for (const row of rows) {
				if (
					!(await hasChannelSubscription(tx, row.connection_id, row.channel_id))
				) {
					await softDeleteStreamingChannelFeed({
						connectionId: row.connection_id,
						channelKey: row.channel_id,
						sql: tx,
					});
				}
			}
			return rows.length;
		});
	}
}

