/**
 * Channel-membership gate for the `channel_messages` read seam — the SQL analog
 * of `./channel-visibility`'s `filterChannelsForRequester`, expressed as a WHERE
 * fragment so raw-SQL callers (watcher @feed sources, query_sql) read chat
 * transcripts with the same fail-closed membership contract.
 *
 * Rule (keyed on the channel identity rather than `events.entity_ids`, because
 * `channel_messages` carries no entity_ids), matching `getConnectionEnforcement`'s
 * three states:
 *   - `not-graphed` (NO acl state row for the connection) → unconstrained (legacy
 *     fence / org-open — the passthrough the whole authz program uses);
 *   - `enforced` (acl row is full + fresh) → visible ONLY when the requester is
 *     `member_of` the `channel` entity keyed `slack_channel_id = UPPER(team:chan)`,
 *     where the team is resolved from the row's connection;
 *   - `stale` / partial / failed (acl row EXISTS but isn't fresh-enforcing) →
 *     fails CLOSED (neither branch matches). A bare `NOT IN (enforced)` would
 *     instead leak a channel whose ACL snapshot merely aged out.
 *
 * Fail-closed: a headless/null principal, an enforced channel the requester
 * doesn't belong to, or a stale-ACL connection all see nothing. This is what
 * makes a (headless) watcher run safe to read a streaming @feed — it reads only
 * not-graphed channels; enforced/stale ones return zero rows, so their content
 * never reaches the shared recap.
 *
 * Requester resolution is the auth-signup `$member` claim only (same as
 * `compileResourceVisibility`) — the recap/query_sql reader is a web/app user, not
 * an in-chat author, so the platform user-id fallback isn't needed on this seam.
 *
 * Platform-parametric: the channel-key match is emitted once per registered chat
 * platform (each contributes its `channelNamespace` + `channelKeySql` via the
 * channel-read-identity registry), gated on the row's `platform`. This file names
 * no connector; adding a chat platform is a registry entry, not a SQL edit.
 */

import { CHANNEL_READ_IDENTITIES } from './sources.js';
import { enforcedConnectionsSelectSql } from './acl-state.js';
import type { ChannelReadIdentity } from '@lobu/connector-sdk';
import type { AuthzScope } from './scope.js';

/**
 * Predicate for a `channel_messages` table (alias has `connection_id` [text
 * runtime id], `channel_id` [bare], `organization_id`). Binds two params from
 * `baseParamIndex`: the org id and the principal. Returns an `AND (...)` fragment
 * (no leading space).
 *
 * `channel_messages.connection_id` and `authz_source_acl_state.connection_id` are
 * BOTH the runtime connection id (see `slack-acl-sync`/`persistChannelMessage`),
 * so the enforced-set membership check compares like-for-like. The channel entity
 * is team-scoped (`T:C`), so the team is resolved from the row's connection
 * (`external_tenant_id` / `config.chatMetadata.teamId`), matched by slug via both
 * the BYO (`agentconn-<id>`) and slack-install (`<id>`) namespaces.
 */
export function compileChannelMessagesVisibility(
  scope: AuthzScope,
  baseParamIndex: number,
  tableAlias: string,
  // The registered chat platforms whose channel gate is emitted. Defaults to the
  // production registry; injectable so the multi-platform OR (≥2 branches) can be
  // exercised without registering a real second connector.
  identities: ChannelReadIdentity[] = CHANNEL_READ_IDENTITIES,
): { sql: string; params: Array<string | null> } {
  const orgParam = `$${baseParamIndex}::text`;
  const userParam = `$${baseParamIndex + 1}::text`;

  // The requester's `$member` entity, resolved on the auth-signup claim only
  // (same guard as compileResourceVisibility — server-written, unforgeable).
  const requesterMemberSubquery = `(
    SELECT mei.entity_id
    FROM public.entity_identities mei
    JOIN public.entities me
      ON me.id = mei.entity_id
     AND me.organization_id = mei.organization_id
     AND me.deleted_at IS NULL
    JOIN public.entity_types met
      ON met.id = me.entity_type_id
     AND met.organization_id = me.organization_id
     AND met.slug = '$member'
    WHERE mei.organization_id = ${orgParam}
      AND mei.namespace = 'auth_user_id'
      AND mei.identifier = ${userParam}
      AND mei.source_connector = 'auth:signup'
      AND mei.deleted_at IS NULL
    LIMIT 1
  )`;

  // The tenant/team the channel key is scoped by, resolved from the row's
  // connection (platform-neutral): the row's own team_id, else the connection's
  // external tenant id / chatMetadata teamId. Passed as the team expression to
  // each platform's channel-key builder.
  const teamExpr = `COALESCE(
    ${tableAlias}.team_id,
    conn.external_tenant_id,
    conn.config->'chatMetadata'->>'teamId'
  )`;

  // One channel-membership EXISTS branch per registered chat platform: the
  // requester is `member_of` the `$resource` entity keyed by THIS platform's
  // channel identity + key expression, gated on the row's platform. OR-ed so a
  // multi-platform transcript table is covered without naming any connector.
  const membershipBranch = (
    channelNamespace: string,
    channelKeySql: string,
  ): string => `EXISTS (
          SELECT 1
          FROM public.connections conn
          JOIN public.entity_identities cei
            ON cei.organization_id = ${orgParam}
           AND cei.namespace = '${channelNamespace}'
           AND cei.deleted_at IS NULL
           AND cei.identifier = ${channelKeySql}
          JOIN public.entity_relationships rr
            ON rr.organization_id = ${orgParam}
           AND rr.to_entity_id = cei.entity_id
           AND rr.deleted_at IS NULL
          JOIN public.entity_relationship_types rt
            ON rt.id = rr.relationship_type_id
           AND rt.organization_id = rr.organization_id
           AND rt.slug = 'member_of'
          WHERE conn.organization_id = ${orgParam}
            AND conn.slug IN (${tableAlias}.connection_id, 'agentconn-' || ${tableAlias}.connection_id)
            AND rr.from_entity_id = ${requesterMemberSubquery}
        )`;

  const platformBranches = identities.map((identity) => {
    const keySql = identity.channelKeySql(teamExpr, `${tableAlias}.channel_id`);
    return `(${tableAlias}.platform = '${identity.platform}' AND ${membershipBranch(
      identity.channelNamespace,
      keySql,
    )})`;
  });
  // No registered chat platform → nothing is member-visible; only the
  // not-graphed passthrough can match. FALSE keeps the enforced branch closed.
  const memberVisible = platformBranches.length > 0 ? platformBranches.join('\n        OR ') : 'FALSE';

  // Fail-closed on stale: a connection is visible ONLY when it has NO acl state
  // row at all (never onboarded → legacy fence, org-visible) OR it is
  // full+fresh-enforced AND the requester is a channel member. A connection whose
  // acl row EXISTS but isn't currently fresh-enforcing (stale / partial / failed)
  // matches neither branch → its transcripts are dropped. This mirrors
  // getConnectionEnforcement's `not-graphed` (passthrough) vs `stale` (fail
  // closed) split — NOT a bare `NOT IN (enforced)`, which would leak a channel
  // whose ACL snapshot merely aged out.
  const sql = `AND (
      NOT EXISTS (
        SELECT 1 FROM public.authz_source_acl_state a
        WHERE a.organization_id = ${orgParam}
          AND a.connection_id = ${tableAlias}.connection_id
      )
      OR (
        ${tableAlias}.connection_id IN (${enforcedConnectionsSelectSql(orgParam)})
        AND (
          ${memberVisible}
        )
      )
    )`;
  return { sql, params: [scope.organizationId, scope.principal] };
}
/**
 * The chat channel visibility gate — "which channels may THIS requester read?"
 *
 * Reads the `member_of` edges the chat ACL sync materializes (via the generic
 * access-graph engine): a requester may recall a channel's transcript iff their
 * `$member` entity is
 * `member_of` that channel. This is the two-sided, fail-closed gate from the
 * authz program (docs/plans/authz-acl-permission-program.md §4) applied to chat
 * recall: the existing per-agent channel fence is one side (the agent only sees
 * its bound channels); this is the other (the user only sees channels they
 * belong to). The two INTERSECT — an agent acting for a user never widens past
 * either bound.
 *
 * Enforcement is per-connection and OFF by default: a connection's rows are
 * gated only once it has a fresh `authz_source_acl_state` row (`acl_support
 * = 'full'` AND `freshness_state = 'fresh'`). A connection that was NEVER graphed
 * (no `authz_source_acl_state` row) keeps the existing per-agent behavior, so an
 * absent graph never silently hides a channel. But once a row exists, anything
 * short of full+fresh — partial/none support, stale/failed freshness, or a fresh
 * row aged past the window — fails CLOSED rather than passing through, so a
 * half-built or stalled graph can never mis-enforce.
 *
 * Fail-closed: for an ENFORCED connection, a channel is dropped unless the
 * requester is provably a member. An unresolved requester (anonymous/headless,
 * or no `$member` in this org) sees NONE of an enforced connection's channels.
 */

import { type DbClient, pgTextArray } from '../db/client.js';
import { getConnectionEnforcement, rowToChannelKey } from './acl-state.js';
import { CHANNEL_READ_IDENTITIES, channelReadIdentityFor } from './sources.js';

/** A bound channel the gate decides on. Mirrors the fields `resolveBoundChannelRows`
 * returns (`id` is the connection id). */
export interface GatedChannelRow {
  /** Connection id that owns the channel subscription. */
  id: string;
  platform: string;
  /** As projected from the Behavior — may be platform-prefixed (`slack:C…`) or bare. */
  channel_id: string;
  /** Workspace/tenant id (Slack `T…`); required to form the team-scoped key. */
  team_id: string | null;
}

/** A (platform, team) pair whose connection is actively enforcing — used to
 * resolve an in-chat requester by that platform's team-scoped user key. */
interface EnforcingTenant {
  platform: string;
  teamId: string;
}

/**
 * Resolve the requester's `$member` entity id in a SPECIFIC org. Restricted to
 * the auth-server signup claim (`namespace='auth_user_id'`,
 * `source_connector='auth:signup'`) so a user-supplied identity row can't hijack
 * the lookup — the same guard `resolveTenantMember` uses, but scoped to the org
 * the read happens in rather than the user's personal org. Returns null when the
 * user has no `$member` here (→ fail closed for enforced connections).
 */
export async function resolveRequesterMemberEntityId(
  sql: DbClient,
  organizationId: string,
  userId: string | null,
): Promise<number | null> {
  if (!userId) return null;
  const rows = await sql<{ entity_id: number }>`
		SELECT e.id AS entity_id
		FROM entity_identities ei
		JOIN entities e
		  ON e.id = ei.entity_id
		 AND e.organization_id = ei.organization_id
		 AND e.deleted_at IS NULL
		JOIN entity_types et
		  ON et.id = e.entity_type_id
		 AND et.organization_id = e.organization_id
		 AND et.slug = '$member'
		WHERE ei.organization_id = ${organizationId}
		  AND ei.namespace = 'auth_user_id'
		  AND ei.identifier = ${userId}
		  AND ei.deleted_at IS NULL
		  AND ei.source_connector = 'auth:signup'
		LIMIT 1
	`;
  return rows.length > 0 ? Number(rows[0].entity_id) : null;
}

/**
 * Fallback requester resolution for someone talking to the bot INSIDE a chat
 * platform, where the only id we have is their platform user id (the message
 * author), not an `auth_user_id`. For each enforcing (platform, team) tenant,
 * builds that platform's team-scoped user key (Slack: `T…:U…` under
 * `slack_user_id`) via the channel-read-identity registry and looks it up.
 * Without this, an in-chat requester always misses the auth lookup and fails
 * closed even on channels they belong to.
 *
 * Safe against hijack the same way the auth path is: the platform user-id claim
 * is only ever written server-side (by the graph builder / login promotion),
 * never from user-supplied input, so resolving on it can't be forged. Returns
 * the first entity that owns any such claim, or null.
 */
async function resolveRequesterByChatUserId(
  sql: DbClient,
  organizationId: string,
  userId: string | null,
  tenants: EnforcingTenant[],
): Promise<number | null> {
  if (!userId || tenants.length === 0) return null;
  // Group the team-scoped user keys by their namespace (a platform may share a
  // namespace across teams), so one indexed lookup covers each namespace.
  const keysByNamespace = new Map<string, Set<string>>();
  for (const { platform, teamId } of tenants) {
    const identity = channelReadIdentityFor(platform);
    if (!identity) continue;
    const key = identity.buildUserKey(teamId, userId);
    if (!key) continue;
    let set = keysByNamespace.get(identity.userNamespace);
    if (!set) {
      set = new Set<string>();
      keysByNamespace.set(identity.userNamespace, set);
    }
    set.add(key);
  }
  for (const [namespace, keys] of keysByNamespace) {
    const rows = await sql<{ entity_id: number }>`
			SELECT ei.entity_id
			FROM entity_identities ei
			JOIN entities e
			  ON e.id = ei.entity_id
			 AND e.organization_id = ei.organization_id
			 AND e.deleted_at IS NULL
			WHERE ei.organization_id = ${organizationId}
			  AND ei.namespace = ${namespace}
			  AND ei.identifier = ANY(${pgTextArray([...keys])}::text[])
			  AND ei.deleted_at IS NULL
			LIMIT 1
		`;
    if (rows.length > 0) return Number(rows[0].entity_id);
  }
  return null;
}

/**
 * Resolve the requester to a `$member` entity id, combining BOTH paths the
 * authz program supports: prefer the auth-server signup claim (web/app sign-in),
 * then fall back to the platform's team-scoped user claim for someone talking to
 * the bot INSIDE a chat platform (whose only id is a platform user id).
 * `enforcingTenants` scopes the chat fallback to the (platform, team) tenants
 * whose connections are actually enforcing. Returns null when neither resolves
 * (→ fail closed).
 *
 * The single resolver shared by the gate ({@link filterChannelsForRequester})
 * and the audience read's "you" highlight, so the two never disagree on who the
 * requester is.
 */
export async function resolveRequesterMember(
  sql: DbClient,
  organizationId: string,
  userId: string | null,
  enforcingTenants: EnforcingTenant[],
): Promise<number | null> {
  if (!userId) return null;
  const byAuth = await resolveRequesterMemberEntityId(sql, organizationId, userId);
  if (byAuth !== null) return byAuth;
  return resolveRequesterByChatUserId(sql, organizationId, userId, enforcingTenants);
}

/** Every registered chat-channel identity namespace — the channel resource key
 * namespaces the member-visibility read unions over. */
const CHANNEL_KEY_NAMESPACES: string[] = [
  ...new Set(CHANNEL_READ_IDENTITIES.map((c) => c.channelNamespace)),
];

/**
 * The team-scoped channel keys the member can read, via `member_of` edges to
 * `$resource` entities carrying any registered chat-channel identity (Slack:
 * `slack_channel_id` = `T…:C…`). Unions across every registered chat platform's
 * channel namespace so a member spanning platforms sees all their channels.
 */
export async function getVisibleChannelKeysForMember(
  sql: DbClient,
  organizationId: string,
  memberEntityId: number,
): Promise<Set<string>> {
  if (CHANNEL_KEY_NAMESPACES.length === 0) return new Set();
  const rows = await sql<{ channel_key: string }>`
		SELECT ei.identifier AS channel_key
		FROM entity_relationships r
		JOIN entity_relationship_types rt
		  ON rt.id = r.relationship_type_id
		 AND rt.organization_id = r.organization_id
		 AND rt.slug = 'member_of'
		JOIN entity_identities ei
		  ON ei.entity_id = r.to_entity_id
		 AND ei.organization_id = r.organization_id
		 AND ei.namespace = ANY(${pgTextArray(CHANNEL_KEY_NAMESPACES)}::text[])
		 AND ei.deleted_at IS NULL
		WHERE r.organization_id = ${organizationId}
		  AND r.from_entity_id = ${memberEntityId}
		  AND r.deleted_at IS NULL
	`;
  return new Set(rows.map((r) => String(r.channel_key)));
}

/**
 * Filter bound channels down to what the requester may actually read. By
 * default, channels on never-graphed connections preserve legacy access;
 * callers granting access to non-owners can disable that fallback. Channels on
 * enforced connections survive only when the requester is provably `member_of`
 * them. An enforced channel with no team id, or an unresolvable requester, is
 * dropped.
 *
 * Returns the surviving rows (same objects, filtered) — the caller keeps its
 * existing per-channel query shape, just over a possibly-smaller set.
 */
export async function filterChannelsForRequester<T extends GatedChannelRow>(
  sql: DbClient,
  params: {
    organizationId: string;
    userId: string | null;
    rows: T[];
    allowNotGraphed?: boolean;
  },
): Promise<T[]> {
  const { organizationId, userId, rows, allowNotGraphed = true } = params;
  if (rows.length === 0) return rows;

